require "application_system_test_case"

class ZzCompareTest < ApplicationSystemTestCase
  SELECTORS = [ ".admin-header", ".breadcrumbs a", ".admin-main h1", ".card", ".field-label", "textarea.input",
                ".option-row .input", ".option-row .checkbox", ".field-hint", ".btn--pink", ".btn--ghost", ".buttons", ".option-rows", ".option-row" ].freeze
  PROPS = %w[font-size font-weight color background-color padding margin border-radius border width height gap min-height].freeze

  def dump_styles
    script = <<~JS
      (() => {
        const sels = #{SELECTORS.to_json};
        const props = #{PROPS.to_json};
        const out = {};
        for (const s of sels) {
          const el = [...document.querySelectorAll(s)].find(e => e.offsetParent !== null || getComputedStyle(e).position === 'fixed') || document.querySelector(s);
          if (!el) { out[s] = null; continue; }
          const cs = getComputedStyle(el);
          out[s] = Object.fromEntries(props.map(p => [p, cs.getPropertyValue(p)]));
          const r = el.getBoundingClientRect();
          out[s].rect = [Math.round(r.width), Math.round(r.height)];
        }
        return out;
      })()
    JS
    page.evaluate_script(script)
  end

  test "compare" do
    page.driver.browser.set_viewport(width: 1280, height: 900)
    visit "file:///app/docs/mockups/question-form.html"
    mock = dump_styles
    quiz = build_quiz(title: "Frontend Fest 2026")
    visit "/moderate/quizzes/#{quiz.id}/questions/new"
    fill_in "Question", with: "Which planet is the largest?"
    fill_in "Option 1", with: "Jupiter"
    check "Option 1 is correct"
    fill_in "Option 2", with: "Saturn"
    fill_in "Option 3", with: "Earth"
    click_button "Save question"
    ours = dump_styles
    File.write("/tmp/explore/compare_q.json", JSON.pretty_generate("mock" => mock, "ours" => ours))
  end
end
EOF
timeout 900 bin/rails test test/system/zz_compare_test.rb 2>&1 | tail -2 && ruby -rjson -e '
d = JSON.parse(File.read("/tmp/explore/compare_q.json"))
d["mock"].each do |sel, props|
  ours = d["ours"][sel]
  next puts("#{sel}: mock=#{props.inspect[0,160]} ours=MISSING") if ours.nil? || props.nil?
  diffs = props.keys.select { |k| props[k] != ours[k] }
  puts "#{sel}: #{diffs.empty? ? "same" : diffs.map { |k| "#{k}: mock=#{props[k]} ours=#{ours[k]}" }.join(" | ")}"
end'

